(()=>{'use strict';
const D=window.ACADEMY_CONTENT,main=document.getElementById('main');
const DEFAULT={name:'',grade:3,progress:{},mistakes:{},attempts:[],daily:{},prefs:{sound:false,motion:true},last:null,focusSessions:0,mapBest:{},timelineBest:{},questBest:{}};
let state,config={teacher:'مستر كريم شعبان',phone:'201127838761',year:'2026 / 2027',location:'سنتر المروة',facebook:'https://www.facebook.com/share/p/1FZoQeVggw/',cloud:{url:'',anonKey:''}};
try{state=validateState(JSON.parse(localStorage.getItem('karim-academy-state')))||structuredClone(DEFAULT);}catch{state=structuredClone(DEFAULT);}
let route='',quiz=null,quizTimer=null,clockTimer=null,flashIndex=0,activeLesson=null,stage='hook',mapGame=null,timelineGame=null,quest=null,audioCtx,cloudSession=null,toastTimer,worldPaths=[],installPrompt=null;
const grades={1:'الأول',2:'الثاني',3:'الثالث'},letters=['أ','ب','ج','د'],esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=x=>new Intl.NumberFormat('ar-EG').format(x),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],localDay=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
function validateState(v){if(!v||typeof v!=='object'||Array.isArray(v))return null;return{...structuredClone(DEFAULT),...v,name:String(v.name||'').slice(0,40),grade:[1,2,3].includes(Number(v.grade))?Number(v.grade):3,progress:obj(v.progress),mistakes:obj(v.mistakes),attempts:Array.isArray(v.attempts)?v.attempts.filter(x=>x&&typeof x==='object').slice(-100):[],prefs:{...DEFAULT.prefs,...obj(v.prefs)},daily:obj(v.daily),mapBest:obj(v.mapBest),timelineBest:obj(v.timelineBest),questBest:obj(v.questBest)};}
function obj(v){return v&&typeof v==='object'&&!Array.isArray(v)?v:{};}
function save(){try{localStorage.setItem(cloudSession?.user?.id?'karim-academy-user-'+cloudSession.user.id:'karim-academy-state',JSON.stringify(state));}catch{toast('المتصفح لم يسمح بحفظ التقدم؛ صدّر نسخة احتياطية من صفحة رحلتي.');}scheduleCloudSave();}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
function gradeClass(g){document.body.classList.remove('grade-1','grade-2','grade-3');if(g)document.body.classList.add('grade-'+g);}
function gradeTabs(g,page){return`<div class="grade-tabs" aria-label="اختيار الصف">${[1,2,3].map(x=>`<a class="tab ${x===g?'active':''}" href="#${page}/${x}">${grades[x]} الإعدادي</a>`).join('')}</div>`;}
function head(title,sub,g,page='portal'){return`<div class="wrap page-top"><div class="breadcrumb"><a href="#home">الرئيسية</a><span>←</span>${g?`<a href="#portal/${g}">${grades[g]} الإعدادي</a>`:esc(title)}</div><div class="eyebrow">ما وراء الحدث / ${g?'بوابة '+grades[g]+' الإعدادي':'مستر كريم شعبان'}</div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}${g?gradeTabs(g,page):''}</div>`;}
function sectionHead(k,t,s='',link=''){return`<div class="section-head"><div><div class="eyebrow">${k}</div><h2>${t}</h2>${s?`<p>${s}</p>`:''}</div>${link}</div>`;}
function allQuestions(g){return D.lessons.filter(l=>l.grade===g).flatMap(l=>l.questions.map(q=>({...q,lesson:l.id,lessonTitle:l.title})));}
function rng(seed){let a=2166136261;for(const c of String(seed))a=Math.imul(a^c.charCodeAt(0),16777619);return()=>{a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function shuffled(items,seed){let a=[...items],r=rng(seed||Date.now());for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function questionById(id){for(const l of D.lessons){const q=l.questions.find(q=>q.id===id);if(q)return{...q,lesson:l.id,lessonTitle:l.title};}return null;}
function status(l){const p=state.progress[l.id];return p?.best>=75?'<span class="status done">✓ أتقنت الدرس</span>':p?'<span class="status">◌ بدأت الرحلة</span>':'<span class="status">لم تبدأ بعد</span>';}
function lessonCard(l){return`<a class="card lesson-card" href="#lesson/${l.id}"><div class="actions"><span class="pill accent">${esc(l.subject)}</span>${status(l)}</div><h3>${esc(l.title)}</h3><p>${esc(l.hook)}</p><div class="bottom"><span>شرح • مراجعة • تحدّي</span><span>افتح الملف ←</span></div></a>`;}
function globe(){return`<svg viewBox="0 0 440 440" aria-hidden="true"><defs><radialGradient id="g"><stop stop-color="#252f35"/><stop offset="1" stop-color="#10191f"/></radialGradient><clipPath id="round"><circle cx="220" cy="220" r="162"/></clipPath></defs><circle cx="220" cy="220" r="184" fill="none" stroke="#e9b76025"/><circle cx="220" cy="220" r="162" fill="url(#g)" stroke="#e9b76060"/><g clip-path="url(#round)" fill="none" stroke="#c8aa6c20"><ellipse cx="220" cy="220" rx="70" ry="162"/><ellipse cx="220" cy="220" rx="130" ry="162"/><ellipse cx="220" cy="220" rx="162" ry="60"/><ellipse cx="220" cy="220" rx="162" ry="116"/><path d="M58 220H382M220 58V382"/></g><g fill="#a3936755" stroke="#c9b78555"><path d="M148 94L176 88 192 104 184 122 199 140 189 161 167 172 157 198 137 187 127 159 113 151 99 130 121 112Z"/><path d="M157 194L183 203 194 227 183 263 166 295 147 281 136 240 143 215Z"/><path d="M239 103L282 99 325 126 351 171 335 196 310 196 286 182 269 198 252 171 228 163 209 137Z"/><path d="M227 174L259 174 277 199 261 239 244 269 222 242 208 207Z"/><path d="M317 262L347 254 359 276 341 294 317 284Z"/></g><circle cx="248" cy="184" r="5" fill="#e9b760"/><circle cx="248" cy="184" r="14" stroke="#e9b76060" fill="none"/><path d="M248 184Q220 110 146 129" stroke="#e9b76077" stroke-dasharray="4 6" fill="none"/><text x="220" y="420" text-anchor="middle" fill="#8c826e" font-size="9" font-family="monospace" letter-spacing="4">EVERY PLACE HAS A STORY</text></svg>`;}
function home(){gradeClass(null);const total=D.lessons.length;main.innerHTML=`<div class="wrap"><section class="hero"><div class="hero-copy reveal"><div class="pill accent"><span class="dot"></span> الدراسات الاجتماعية.. بحكاية مختلفة</div><h1 style="margin-top:22px">وراء كل مكان..<br><span>حكاية تستاهل</span><br>تفهمها.</h1><p class="lede">التاريخ مليان قرارات، والجغرافيا مليانة أسرار.<br>تعال نفتح الملفات، نربط الخيوط، ونشوف الصورة كاملة.</p><div class="actions"><a class="btn primary" href="#choose">ابدأ رحلتك <span>←</span></a><a class="btn" href="#booking">احجز حصتك <span>↗</span></a></div><div class="hero-meta"><div><b>٣ بوابات</b>أولى • تانية • تالتة</div><div><b>${n(total)} درسًا</b>ملفات تعلم مختصرة</div><div><b>افهم. اربط. افتكر.</b>خطوة ورا خطوة</div></div></div><div class="hero-art reveal"><div class="art-coordinate top">30° N / 31° E — CAIRO</div><div class="globe-art">${globe()}<div class="orbit"></div><div class="orbit two"></div></div><div class="floating-card one"><span class="accent">✦ خريطة مش مجرد أسماء</span><b>كل موقع.. له تأثير</b><p>اكتشف العلاقة بين المكان والحكاية.</p></div><div class="floating-card two"><b>ملف ١٨٠٥ <span class="accent">↗</span></b><p>إزاي قرار واحد يفتح فصلًا جديدًا؟</p></div><div class="teacher-chip"><div><b>مستر كريم شعبان</b><small>دراسات اجتماعية • تاريخ</small></div><img src="assets/profile.webp" alt="كريم شعبان" width="43" height="43"></div><div class="art-coordinate bottom">EXPLORE / CONNECT / REMEMBER</div></div></section></div><div class="ticker"><span>ملفات تاريخية</span><span>خرائط تفاعلية</span><span>تحدّيات وألغاز</span><span>مراجعة أخطائك</span></div><section id="choose" class="section wrap">${sectionHead('اختار عالمك','رحلتك تبدأ من صفّك.','نفس الحماس، وحكايات وتحدّيات مناسبة لكل مرحلة.')}<div class="grid three">${[1,2,3].map((g,i)=>`<a href="#portal/${g}" class="card grade-card g${g}"><span class="grade-num">0${g}</span><div><small>بوابة ${i+1} / الدراسات الاجتماعية</small><h3>${grades[g]} الإعدادي</h3><p>${['من إفريقيا وأسرار النيل.. إلى مصر القديمة.','من آسيا وأوروبا.. إلى حضارات صنعت أثرًا.','من قارات العالم الجديد.. إلى تاريخ مصر الحديث.'][i]}</p></div><div class="line-link"><span>${n(D.lessons.filter(l=>l.grade===g).length)} ملف تعلم • الترم الأول</span><span>افتح البوابة ←</span></div></a>`).join('')}</div></section><section class="section wrap"><div class="featured"><div class="featured-copy"><div class="eyebrow">جرّب بنفسك / ملف تفاعلي</div><h2>القرار كان بإيدك..<br>كنت هتختار إيه؟</h2><p>ادخل غرفة قرارات التاريخ. اقرأ الموقف، اختار، واكتشف العلاقة بين القرار والنتيجة.</p><a class="btn primary" href="#decision/${state.grade}">ادخل غرفة القرارات ←</a><p class="muted" style="font-size:10px;margin-bottom:0">مواقف تخيّلية للتفكير، مع تفسير يربطها بوقائع تاريخية.</p></div><div class="case-art" aria-hidden="true"><div class="case-file"><span>1805</span><b>ما وراء الحدث</b><p>الدليل الأول: كل قرار له سياق.<br>الدليل الثاني: النتيجة جزء من الحكاية.</p></div></div></div></section><section class="section wrap">${sectionHead('طريقتنا','المعلومة ليها رحلة.')}<div class="grid three steps"><div class="step"><h3>افهمها</h3><p>ابدأ بسؤال. شوف الدليل وافهم الحكاية.</p></div><div class="step"><h3>اربطها</h3><p>المكان بالحدث، والسبب بالنتيجة.</p></div><div class="step"><h3>وافتكرها</h3><p>تحدّيات قصيرة ومراجعة لما يحتاج تدريبًا.</p></div></div></section><section class="section wrap">${sectionHead('جرعة حماس','خمس دقائق.. وتعرف مستواك.','تحدّي يومي مختلف، ونتيجة تقول لك تراجع إيه.')}<div class="grid three">${[1,2,3].map(g=>`<div class="card"><span class="pill accent">${grades[g]} الإعدادي</span><h3 style="margin:18px 0">مهمة النهارده</h3><p style="font-size:12px;margin-bottom:20px">٥ أسئلة تجمع بين التاريخ والجغرافيا، مع شرح لكل إجابة.</p><a href="#daily/${g}" class="btn small">ابدأ التحدّي ←</a></div>`).join('')}</div></section><section class="section wrap about-grid"><div><div class="eyebrow">عن مستر كريم</div><h2>الحصة تبدأ بسؤال..<br>وتنتهي بصورة أوضح.</h2><p>أنا كريم شعبان، أدرس التاريخ بكلية التربية، جامعة عين شمس. أدرّس الدراسات الاجتماعية والتاريخ، وبحب أحوّل الأفكار الكبيرة لقصص وخرائط وتجارب تخلّيك تفكر وتشارك.</p><div class="actions"><a class="btn" href="#about">اعرف أكثر ←</a><a class="btn ghost" href="#booking">نتقابل في الحصة ↗</a></div></div><div class="about-photo"><img src="assets/profile.webp" alt="مستر كريم شعبان" loading="lazy" width="500" height="500"></div></section><section class="section wrap faq">${sectionHead('قبل ما تبدأ','أسئلة ممكن تكون في بالك.')}<details><summary>هل أقدر أجرب من غير حساب؟</summary><p>أيوه. الدروس والتحديات متاحة، وتقدمك محفوظ في المتصفح. تقدر تصدّره وتستعيده من صفحة رحلتي.</p></details><details><summary>لو غلطت في سؤال، إيه اللي يحصل؟</summary><p>هتشوف تفسير الإجابة، والسؤال يروح لقائمة «راجع اللي لخبطك». لما تجاوبه صح في تدريب جديد يتشال من القائمة.</p></details><details><summary>المحتوى بيغطي إيه؟</summary><p>ملفات شرح ومراجعة مختصرة للترم الأول للصفوف الثلاثة. المحتوى للتعلم والتدريب بجانب كتاب المدرسة وشرح مستر كريم، وليس بديلًا عن الكتاب بالكامل.</p></details><details><summary>أقدر أحجز أونلاين أو حضوري؟</summary><p>أيوه. افتح صفحة الحجز وحدد صفك وطريقة الحصة، وبعدها ابعت طلبك بنفسك على واتساب لمعرفة المواعيد المتاحة.</p></details></section><section class="section wrap"><div class="cta"><div><div class="eyebrow">نفتح أول ملف؟</div><h2>المنهج أقرب.. لما تفهم حكايته.</h2><p>اختار صفك، وابدأ أول تحدّي النهارده.</p></div><a href="#portal/${state.grade}" class="btn primary">ابدأ الرحلة ←</a></div></section>`;}
function portal(g){setGrade(g);main.innerHTML=head('رحلتك في الدراسات','الترم الأول • افتح ملفًا، افهم حكايته، وجرّب بنفسك.',g)+`<section class="wrap section" style="padding-top:15px"><div id="continue-banner"></div><div class="toolbar"><label class="sr-only" for="lesson-search">ابحث عن درس</label><input id="lesson-search" class="input" type="search" placeholder="ابحث عن درس أو فكرة…"><button class="filter active" data-subject="all">كل الملفات</button><button class="filter" data-subject="جغرافيا">الجغرافيا</button><button class="filter" data-subject="تاريخ">التاريخ</button><select class="input" id="unit-filter" aria-label="الوحدة"><option value="all">كل الوحدات</option>${D.units[g].map((u,i)=>`<option value="${i+1}">${esc(u)}</option>`).join('')}</select></div><div id="lesson-list"></div><div class="note">هذه ملفات تعلم مختصرة وتدريبات أصلية. استخدمها بجانب كتاب المدرسة وشرح الحصة. <a href="#sources" style="color:var(--accent)">المحتوى والمصادر ←</a></div></section>`;let subject='all';const update=()=>{const term=$('#lesson-search').value.trim(),unit=$('#unit-filter').value;const ls=D.lessons.filter(l=>l.grade===g&&(subject==='all'||l.subject===subject)&&(unit==='all'||l.unit===Number(unit))&&[l.title,l.hook,...l.sections.map(s=>s.body)].join(' ').includes(term));$('#lesson-list').innerHTML=`<p class="search-count">${n(ls.length)} ملف تعلم</p>`+D.units[g].map((u,i)=>{const group=ls.filter(l=>l.unit===i+1);return group.length?`<h2 class="unit-heading"><span>0${i+1}</span>${esc(u)}</h2><div class="grid three">${group.map(lessonCard).join('')}</div>`:'';}).join('')+(ls.length?'':'<div class="empty"><h3>مفيش نتيجة بالبحث ده</h3><p>جرّب كلمة أخرى أو اختار كل الملفات.</p></div>');};$('#lesson-search').addEventListener('input',update);$('#unit-filter').addEventListener('change',update);$$('[data-subject]').forEach(b=>b.onclick=()=>{subject=b.dataset.subject;$$('[data-subject]').forEach(x=>x.classList.toggle('active',x===b));update();});const ls=D.lessons.filter(l=>l.grade===g),done=ls.filter(l=>state.progress[l.id]?.best>=75).length,last=ls.find(l=>l.id===state.last)||ls.find(l=>!state.progress[l.id]?.best)||ls[0];$('#continue-banner').innerHTML=`<div class="dashboard-banner"><div><small>${state.name?'أهلًا '+esc(state.name):'أهلًا بيك في الرحلة'}</small><h3>${done?'كمّل.. الصورة بتوضح.':'أول خطوة بتبدأ بسؤال.'}</h3><p>${n(done)} من ${n(ls.length)} درسًا أتقنتها • التالي: ${esc(last.title)}</p><div class="meter"><span style="width:${done/ls.length*100}%"></span></div></div><a class="btn primary small" href="#lesson/${last.id}">${state.last===last.id?'كمّل درسك':'افتح الملف'} ←</a></div>`;update();}
function setGrade(g){g=Number(g);if(![1,2,3].includes(g))g=3;state.grade=g;save();gradeClass(g);$('#mobile-lessons').href='#portal/'+g;$('#mobile-games').href='#games/'+g;}
const STAGES=[['hook','افتح القضية','01'],['explain','افهم الحكاية','02'],['connect','اربط الخيوط','03'],['flash','ثبّت المعلومة','04'],['challenge','ادخل المهمة','05'],['quiz','اختبر فهمك','06']];
function lessonPage(id){const l=D.lessons.find(l=>l.id===id);if(!l){notFound();return;}setGrade(l.grade);activeLesson=l;state.last=id;state.progress[id]={...state.progress[id],started:true,visited:new Date().toISOString()};save();stage=new URLSearchParams(location.hash.split('?')[1]||'').get('stage')||'hook';if(!STAGES.some(s=>s[0]===stage))stage='hook';main.innerHTML=head(l.title,l.hook,l.grade)+`<section class="wrap lesson-layout"><aside class="lesson-side" aria-label="خطوات الدرس"><small>ملف ${n(l.unit)} / ${esc(l.subject)}</small>${STAGES.map(([s,t,i])=>`<button data-stage="${s}" class="${s===stage?'active':''}"><span>${i}</span>${t}</button>`).join('')}</aside><div class="lesson-stage" id="lesson-stage"></div></section>`;$$('[data-stage]').forEach(b=>b.onclick=()=>{stopQuiz();stage=b.dataset.stage;$$('[data-stage]').forEach(x=>x.classList.toggle('active',x===b));renderStage();});renderStage();}
function stageNext(next,label){return`<div class="actions" style="margin-top:25px"><button class="btn primary" id="stage-next">${label||'الخطوة التالية'} ←</button><a class="btn" href="#handout/${activeLesson.id}">ورقة الدرس ↗</a></div>`;}
function renderStage(){const l=activeLesson,box=$('#lesson-stage');if(!box)return;box.className='lesson-stage reveal';flashIndex=0;switch(stage){case'hook':box.innerHTML=`<div class="eyebrow">قبل الشرح / فكّر بصوتك</div><h2>افتح القضية.</h2><div class="hook-card"><span class="pill accent">سؤال البداية</span><h3 style="margin-top:18px">${esc(l.hook)}</h3><p>خد دقيقة، كوّن توقعًا، وبعد الشرح ارجع وقارن توقعك بالدليل.</p><label for="prediction" class="muted" style="font-size:12px">توقعك في سطر</label><textarea id="prediction" class="input" rows="3" placeholder="أنا متوقع إن…">${esc(state.progress[l.id]?.prediction||'')}</textarea><button id="save-prediction" class="btn small" style="margin-top:12px">احفظ توقعك</button></div><div class="grid two">${l.sections.slice(0,2).map(s=>`<div class="card"><h3>${esc(s.title)}</h3><p style="font-size:12px;margin-top:12px">هنفتح الفكرة دي في الشرح، ونشوف أثرها.</p></div>`).join('')}</div>${stageNext('explain','افهم الحكاية')}`;$('#save-prediction').onclick=()=>{state.progress[l.id].prediction=$('#prediction').value.slice(0,2000);save();toast('اتحفظ توقعك. ارجع له بعد الشرح.');};break;
case'explain':box.innerHTML=`<div class="eyebrow">الشرح / الفكرة ثم الدليل</div><h2>افهم الحكاية.</h2>${l.sections.map((s,i)=>`<article class="article-card"><span class="pill">الفكرة ${n(i+1)}</span><h3 style="margin-top:10px">${esc(s.title)}</h3><p>${esc(s.body)}</p></article>`).join('')}<div class="note">شرح مختصر للتعلم والمراجعة؛ أكمل التفاصيل والأنشطة من كتاب المدرسة والحصة.</div>${stageNext('connect','اربط الخيوط')}`;break;
case'connect':box.innerHTML=`<div class="eyebrow">الصورة الكبيرة / ربط بصري</div><h2>اربط الخيوط.</h2><p style="font-size:13px;margin-top:10px">افتح كل فرع وشوف علاقته بباقي الحكاية.</p><div class="mindmap"><div class="mindmap-root">${esc(l.title)}</div><div class="mindmap-branches">${l.sections.map(s=>`<details class="mind-branch"><summary>${esc(s.title)}</summary><p>${esc(s.body)}</p></details>`).join('')}</div></div>${state.progress[l.id].prediction?`<div class="hook-card"><h3>توقعك في البداية</h3><p>${esc(state.progress[l.id].prediction)}</p><p>هل تغيّر بعد ما ربطت الأدلة؟</p></div>`:''}${stageNext('flash','ثبّت المعلومة')}`;break;
case'flash':box.innerHTML=`<div class="eyebrow">بطاقات المراجعة / حاول قبل التقليب</div><h2>افتكرها بطريقتك.</h2><div id="flash-area"></div>${stageNext('challenge','ادخل المهمة')}`;drawFlash();break;
case'challenge':box.innerHTML=`<div class="eyebrow">التطبيق / المهمة تبدأ هنا</div><h2>اختار تحدّيك.</h2><div class="grid two" style="margin-top:25px"><div class="card game-card"><div class="game-icon">⌖</div><h3>تحدّي الخريطة</h3><p>حدد المواقع، واربط كل موقع بمعلومة.</p><a class="btn small" href="#map/${l.grade}">افتح الخريطة ←</a></div><div class="card game-card"><div class="game-icon">⌘</div><h3>${l.timeline.length?'رتّب الحكاية':'خزنة الأسرار'}</h3><p>${l.timeline.length?'رتب المحطات التاريخية، واكتشف التتابع.':'حل ثلاث شفرات من أفكار الدرس لفتح الخزنة.'}</p><a class="btn small" href="#${l.timeline.length?'timeline':'quest'}/${l.id}">ابدأ المهمة ←</a></div></div>${stageNext('quiz','اختبر فهمك')}`;break;
case'quiz':box.innerHTML=`<div class="eyebrow">الاختبار / اعرف مستواك</div><h2>الدليل إنك فهمت.</h2><div class="hook-card"><h3>${n(l.questions.length)} أسئلة من الدرس</h3><p>كل إجابة معاها تفسير. لو غلطت، هتلاقي السؤال في مراجعة أخطائك.</p><button class="btn primary" id="start-lesson-quiz">ابدأ الاختبار ←</button></div><div id="quiz-area"></div>`;$('#start-lesson-quiz').onclick=()=>startQuiz(l.questions.map(q=>({...q,lesson:l.id,lessonTitle:l.title})),{type:'lesson',lesson:l.id,grade:l.grade,target:'#lesson-stage',title:l.title});break;}
const next=$('#stage-next');if(next)next.onclick=()=>{const ns={hook:'explain',explain:'connect',connect:'flash',flash:'challenge',challenge:'quiz'};stage=ns[stage];$$('[data-stage]').forEach(x=>x.classList.toggle('active',x.dataset.stage===stage));renderStage();};}
function drawFlash(){const qs=activeLesson.questions,q=qs[flashIndex];$('#flash-area').innerHTML=`<div class="flash-wrap"><button class="flashcard" id="flashcard" aria-label="قلب البطاقة" aria-pressed="false"><div class="flash-inner"><div class="flash-front"><span class="pill accent">سؤال ${n(flashIndex+1)}</span><h3 style="margin-top:20px">${esc(q.prompt)}</h3><small>فكّر.. وبعدها اضغط لكشف الإجابة ↻</small></div><div class="flash-back" aria-hidden="true"><b>${esc(q.options[q.answer])}</b><p>${esc(q.explanation)}</p></div></div></button></div><div class="flash-controls"><button class="btn small" id="flash-prev" ${flashIndex===0?'disabled':''}>السابق</button><span class="muted">${n(flashIndex+1)} / ${n(qs.length)}</span><button class="btn small" id="flash-next" ${flashIndex===qs.length-1?'disabled':''}>التالي</button></div>`;$('#flashcard').onclick=()=>{const b=$('#flashcard'),flipped=b.classList.toggle('flipped');b.setAttribute('aria-pressed',flipped);b.querySelector('.flash-front').setAttribute('aria-hidden',flipped);b.querySelector('.flash-back').setAttribute('aria-hidden',!flipped);tone('flip');};$('#flash-prev').onclick=()=>{flashIndex=Math.max(0,flashIndex-1);drawFlash();};$('#flash-next').onclick=()=>{flashIndex=Math.min(qs.length-1,flashIndex+1);drawFlash();};}
function games(g){setGrade(g);main.innerHTML=head('ساحة التحدّيات','اختار المهمة المناسبة لك. الدقة أهم من السرعة، وكل محاولة فرصة للتعلم.',g,'games')+`<section class="wrap section" style="padding-top:10px"><div class="grid three">${[['daily','◷','تحدّي الـ٥ دقائق','٥ أسئلة تتغير كل يوم، وتفسير يساعدك تفهم.'],['map','⌖','الخريطة الصامتة','ستة مواقع، وعلاقة تربط المكان بالمعلومة.'],['decision','⌘','غرفة قرارات التاريخ','اقرأ موقفًا تخيليًا واكتشف تفسير كل قرار.'],['escape','◇','خزنة الأسرار','حل ثلاث شفرات لفتح ملف من ملفات صفك.'],['order','↕','رتّب الحكاية','اسحب الأحداث أو استخدم الأسهم لإعادة ترتيبها.'],['group','⚑','معركة الحصة','كود واحد يولّد نفس الأسئلة لكل الزملاء.'],['exam','▤','محاكاة الامتحان','اختبار بوقت، والنتيجة والتفسير بعد التسليم.'],['mistakes','◎','راجع اللي لخبطك','أسئلتك الصعبة ترجع لك في تدريب مركز.'],['focus','◴','غرفة التركيز','جلسة مذاكرة، ثم استراحة قصيرة.']].map(([p,ic,t,d])=>`<div class="card game-card"><div class="game-icon">${ic}</div><h3>${t}</h3><p>${d}</p><a href="#${p}/${g}" class="btn small">ابدأ المهمة ←</a></div>`).join('')}</div><div style="margin-top:55px">${sectionHead('من ألعاب مستر كريم','الألعاب الأصلية.. لسه موجودة.','ألعاب إثرائية ومهارات أساسية؛ اختار اللعبة المناسبة لموضوعك.')}<div class="grid two">${[['Game.html','المهمة المستحيلة','أرشيف أسرار الحملة الفرنسية — ملف إثرائي تاريخي.'],['TimeCapsule.html','كبسولة الزمن','لعبة من مكتبتك الأصلية للمرحلة الابتدائية.'],['space-game.html','مستكشف الفضاء','تدريب على الاتجاهات وقراءة الخرائط.'],['smart-princess-game.html','الأميرة الذكية','لعبة من مكتبتك الأصلية للمرحلة الابتدائية.']].map(([url,t,d])=>`<a class="card" href="${url}"><h3>${t}</h3><p style="font-size:12px;margin:10px 0">${d}</p><span class="btn ghost">افتح اللعبة ←</span></a>`).join('')}</div></div></section>`;}
function daily(g){setGrade(g);const key=localDay()+'-'+g,done=state.daily[key];main.innerHTML=head('مهمة النهارده','٥ أسئلة • ٥ دقائق • فرصة جديدة للفهم.',g,'daily')+`<section class="wrap section" style="padding-top:15px"><div class="quiz-shell"><div class="hook-card"><div class="eyebrow">${esc(localDay())} / التحدّي اليومي</div><h2>جاهز لخمس دقائق؟</h2><p>اختياراتك تتصحح مباشرة، وبعدها يظهر تفسير كل سؤال. لو الوقت انتهى، يظهر ملخص محاولتك.</p>${done?`<p class="success">أفضل نتيجة لك اليوم: ${n(done.best)}٪</p>`:''}<button class="btn primary" id="start-daily">ابدأ التحدّي ←</button></div><div id="quiz-area"></div></div></section>`;$('#start-daily').onclick=()=>startQuiz(shuffled(allQuestions(g),key).slice(0,5),{type:'daily',grade:g,key,seconds:300,target:'.quiz-shell',title:'مهمة النهارده',seed:key});}
function stopQuiz(){clearInterval(quizTimer);quizTimer=null;quiz=null;}
function startQuiz(qs,opts){clearInterval(quizTimer);const seed=opts.seed||Date.now();quiz={questions:shuffled(qs,seed).map(q=>{const choices=shuffled(q.options.map((text,i)=>({text,correct:i===q.answer})),seed+q.id);return{...q,choices};}),opts,index:0,responses:{},finished:false,deadline:opts.seconds?Date.now()+opts.seconds*1000:null};drawQuiz();if(quiz.deadline){quizTimer=setInterval(()=>{if(!quiz||quiz.finished){clearInterval(quizTimer);return;}const left=Math.max(0,Math.ceil((quiz.deadline-Date.now())/1000));const t=$('#quiz-time');if(t)t.textContent=timeText(left);if(left===0)finishQuiz(true);},250);}}
function timeText(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');}
function quizTarget(){return $(quiz.opts.target);}
function drawQuiz(){if(!quiz)return;const{questions,index,opts,responses}=quiz,q=questions[index],answer=responses[q.id],exam=opts.type==='exam',answered=answer!==undefined,target=quizTarget();if(!target)return;target.innerHTML=`<div class="quiz-shell reveal"><div class="quiz-meta"><span>${exam?'محاكاة امتحان':'تحدّي فهم'} / سؤال ${n(index+1)} من ${n(questions.length)}</span>${quiz.deadline?`<span id="quiz-time" class="timer">${timeText(Math.max(0,Math.ceil((quiz.deadline-Date.now())/1000)))}</span>`:''}</div><div class="meter"><span style="width:${(index+1)/questions.length*100}%"></span></div><p class="muted" style="font-size:11px;margin-top:20px">${esc(q.lessonTitle||opts.title)}</p><h2 class="quiz-prompt">${esc(q.prompt)}</h2><div class="options">${q.choices.map((o,i)=>`<button class="option ${answered&&!exam?(o.correct?'correct':i===answer?'wrong':''):answered&&exam&&i===answer?'selected':''}" data-answer="${i}" ${answered&&!exam?'disabled':''}><span>${letters[i]}</span>${esc(o.text)}</button>`).join('')}</div>${answered&&!exam?`<div class="feedback"><b>${q.choices[answer].correct?'✓ إجابة صحيحة':'جرّب تربطها بالدليل'}</b><p>${esc(q.explanation)}</p></div>`:''}<div class="actions">${exam&&index>0?'<button class="btn small" id="quiz-prev">السؤال السابق</button>':''}${answered||exam?`<button class="btn primary" id="quiz-next">${index===questions.length-1?(exam?'راجع ثم سلّم':'شوف النتيجة'):'السؤال التالي'} ←</button>`:''}${exam?'<button class="btn small" id="quiz-submit">تسليم الآن</button>':''}</div></div>`;$$('[data-answer]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.answer);quiz.responses[q.id]=i;if(!exam)tone(q.choices[i].correct?'right':'wrong');drawQuiz();});const next=$('#quiz-next');if(next)next.onclick=()=>{if(quiz.index<questions.length-1){quiz.index++;drawQuiz();}else if(exam)confirmSubmit();else finishQuiz();};const prev=$('#quiz-prev');if(prev)prev.onclick=()=>{quiz.index--;drawQuiz();};const submit=$('#quiz-submit');if(submit)submit.onclick=confirmSubmit;}
function confirmSubmit(){const left=quiz.questions.filter(q=>quiz.responses[q.id]===undefined).length;modal(`<h2>تسليم الامتحان</h2><p style="margin:20px 0">${left?'متبقي '+n(left)+' أسئلة لم تجب عنها.':'أجبت عن كل الأسئلة.'} بعد التسليم تظهر النتيجة والتفسير.</p><div class="actions"><button class="btn primary" id="confirm-submit">سلّم الامتحان</button><button class="btn" id="cancel-submit">ارجع للمراجعة</button></div>`);$('#confirm-submit').onclick=()=>{$('#modal').close();finishQuiz();};$('#cancel-submit').onclick=()=>$('#modal').close();}
function finishQuiz(timeout=false){if(!quiz||quiz.finished)return;quiz.finished=true;clearInterval(quizTimer);const current=quiz,{questions,opts,responses}=current,correct=questions.filter(q=>q.choices[responses[q.id]]?.correct).length,score=Math.round(correct/questions.length*100),date=new Date().toISOString();for(const q of questions){const answer=responses[q.id];if(q.choices[answer]?.correct)delete state.mistakes[q.id];else state.mistakes[q.id]={id:q.id,grade:opts.grade,lesson:q.lesson,date};}if(opts.lesson){state.progress[opts.lesson]={...state.progress[opts.lesson],best:Math.max(score,state.progress[opts.lesson]?.best||0),lastScore:score,completedAt:score>=75?date:state.progress[opts.lesson]?.completedAt};}if(opts.type==='daily')state.daily[opts.key]={best:Math.max(score,state.daily[opts.key]?.best||0),date};state.attempts.push({type:opts.type,grade:opts.grade,score,total:questions.length,correct,date,title:opts.title});state.attempts=state.attempts.slice(-100);save();if(score>=75)celebrate();quizTarget().innerHTML=`<div class="result"><div class="eyebrow" style="justify-content:center">${timeout?'انتهى الوقت':'اكتملت المهمة'}</div><div class="score">${n(score)}<span style="font-size:32px">٪</span></div><h2>${score>=75?'الصورة بتوضح.. كمّل!':'عرفنا نبدأ المراجعة منين.'}</h2><p>${n(correct)} إجابات صحيحة من ${n(questions.length)}. ${score===100?'إتقان ممتاز للمجموعة دي.':'راجع التفسير، وبعدها جرّب من جديد.'}</p><div class="actions"><button class="btn primary" id="quiz-retry">جرّب من جديد ↻</button><a class="btn" href="#mistakes/${opts.grade}">راجع اللي لخبطك</a><button class="btn small" id="share-result">مشاركة النتيجة</button></div></div><div>${questions.map(q=>`<div class="review-row"><span class="pill ${q.choices[responses[q.id]]?.correct?'accent':''}">${q.choices[responses[q.id]]?.correct?'✓ صحيح':responses[q.id]===undefined?'لم تجب':'راجعها'}</span><h3 style="margin-top:12px">${esc(q.prompt)}</h3><p>الإجابة: <b class="success">${esc(q.options[q.answer])}</b></p><p>${esc(q.explanation)}</p><a href="#lesson/${q.lesson}" class="btn ghost small">افتح الشرح ←</a></div>`).join('')}</div>`;$('#quiz-retry').onclick=()=>{const q=opts.type==='daily'?shuffled(allQuestions(opts.grade),opts.key).slice(0,5):questions.map(q=>({...q}));startQuiz(q,{...opts,seed:opts.type==='group'||opts.type==='daily'?opts.seed:Date.now()});};$('#share-result').onclick=()=>shareText(`أنهيت «${opts.title}» مع مستر كريم شعبان بنتيجة ${score}٪ (${correct}/${questions.length}). افهمها.. اربطها.. وافتكرها.`,location.href);}
function mistakes(g){setGrade(g);const qs=Object.keys(state.mistakes).map(questionById).filter(q=>q&&D.lessons.find(l=>l.id===q.lesson).grade===g);main.innerHTML=head('راجع اللي لخبطك','كل سؤال صعب فرصة لفهم أوضح. جاوبه صح في التدريب عشان يخرج من القائمة.',g,'mistakes')+`<section class="wrap section" style="padding-top:15px"><div class="quiz-shell" id="mistake-area">${qs.length?`<div class="dashboard-banner"><div><h3>${n(qs.length)} أسئلة محتاجة مراجعة</h3><p>ابدأ بالتفسير، ثم اختبر نفسك.</p></div><button class="btn primary" id="start-mistakes">درّبني عليها ←</button></div>${qs.map(q=>`<details class="review-row"><summary>${esc(q.prompt)}</summary><p>${esc(q.explanation)}</p><a class="btn small" href="#lesson/${q.lesson}">ارجع للدرس</a></details>`).join('')}`:`<div class="empty"><div class="game-icon">✓</div><h2>قائمة المراجعة فاضية</h2><p>بعد أي اختبار، هنجمع هنا الأسئلة اللي محتاجة تدريب.</p><a href="#daily/${g}" class="btn primary">جرّب تحدّي النهارده ←</a></div>`}</div></section>`;const b=$('#start-mistakes');if(b)b.onclick=()=>startQuiz(qs,{type:'mistakes',grade:g,target:'#mistake-area',title:'مراجعة الأخطاء'});}
function exam(g){setGrade(g);main.innerHTML=head('محاكاة الامتحان','اختبار بوقت. الإجابات والتفسير يظهران بعد التسليم.',g,'exam')+`<section class="wrap section" style="padding-top:15px"><div class="quiz-shell" id="exam-area"><div class="hook-card"><h2>اختار شكل تدريبك.</h2><label for="exam-subject">المادة</label><select id="exam-subject" class="input"><option value="all">تاريخ وجغرافيا</option>تاريخ</option><option>جغرافيا</option></select><label for="exam-count" style="display:block;margin-top:18px">عدد الأسئلة</label><select id="exam-count" class="input"><option value="10">١٠ أسئلة / ١٠ دقائق</option><option value="20">٢٠ سؤالًا / ٢٠ دقيقة</option></select><p style="margin:20px 0">يمكنك تغيير الإجابات والعودة للسؤال السابق. وقت الامتحان يستمر لو خرجت من التبويب. هذه محاكاة تدريبية وليست امتحانًا رسميًا.</p><button class="btn primary" id="start-exam">ابدأ المحاكاة ←</button></div></div></section>`;$('#start-exam').onclick=()=>{const subject=$('#exam-subject').value,count=Number($('#exam-count').value),qs=allQuestions(g).filter(q=>subject==='all'||D.lessons.find(l=>l.id===q.lesson).subject===subject);startQuiz(shuffled(qs,Date.now()).slice(0,count),{type:'exam',grade:g,target:'#exam-area',title:'محاكاة الامتحان',seconds:count*60});};}
function decision(g){setGrade(g);const c=D.cases[g];main.innerHTML=head('غرفة قرارات التاريخ','ادخل الموقف، اقرأ الدليل، واختار خطوتك.',g,'decision')+`<section class="wrap section" style="padding-top:10px"><div class="quiz-shell"><div class="eyebrow">سيناريو تعليمي تخيّلي</div><h2>${esc(c.title)}</h2><div class="hook-card"><p>${esc(c.scene)}</p></div><div class="options">${c.options.map(([t],i)=>`<button class="option" data-decision="${i}"><span>${letters[i]}</span>${esc(t)}</button>`).join('')}</div><div id="decision-feedback" role="status"></div><div class="note">هذا تدريب على تحليل القرار، وليس إعادة تمثيل موثقة لحوار أو قرار تاريخي بعينه.</div></div></section>`;$$('[data-decision]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.decision);$$('[data-decision]').forEach(x=>x.classList.toggle('correct',x===b));$('#decision-feedback').innerHTML=`<div class="feedback"><b>افتح الخيط اللي ورا القرار</b><p>${esc(c.options[i][1])}</p></div><a class="btn small" href="#portal/${g}">ارجع لملفات الصف ←</a>`;tone('flip');});}
function escapeChooser(g,kind='quest'){setGrade(g);const ls=D.lessons.filter(l=>l.grade===g&&(kind!=='timeline'||l.timeline.length));main.innerHTML=head(kind==='quest'?'خزنة الأسرار':'رتّب الحكاية',kind==='quest'?'اختار الملف، وحل شفراته واحدة ورا واحدة.':'اختار خطًا زمنيًا، وأعد الأحداث إلى ترتيبها.',g,kind==='quest'?'escape':'order')+`<section class="wrap section" style="padding-top:10px"><div class="grid three">${ls.map(l=>`<a class="card game-card" href="#${kind}/${l.id}"><span class="pill accent">${esc(l.subject)}</span><h3 style="margin:20px 0">${esc(l.title)}</h3><p>${kind==='quest'?'٣ شفرات • رمز خزنة':'سحب وترتيب • فحص الإجابة'}</p><span class="btn small">افتح الملف ←</span></a>`).join('')}</div></section>`;}
function questPage(id){const l=D.lessons.find(l=>l.id===id);if(!l)return notFound();setGrade(l.grade);quest={lesson:l,index:0,digits:[],questions:shuffled(l.questions,id).slice(0,3),tries:0};main.innerHTML=head('خزنة الأسرار',l.title,l.grade)+`<section class="wrap section" style="padding-top:10px"><div class="quiz-shell" id="quest-area"></div></section>`;drawQuest();}
function drawQuest(){const box=$('#quest-area'),{lesson:l,index,digits,questions}=quest;if(index===3){box.innerHTML=`<div class="center"><div class="game-icon" style="font-size:55px">◇</div><h2>معاك مفاتيح الخزنة.</h2><p style="font-size:13px;margin-top:15px">ركّب الأرقام اللي كسبتها بالترتيب وافتح الملف.</p><div class="code-display">${digits.join(' ')}</div><label for="vault-code">رمز الخزنة</label><input id="vault-code" class="input" inputmode="numeric" maxlength="3" dir="ltr" style="max-width:220px;text-align:center;display:block;margin:18px auto"><button class="btn primary" id="unlock">افتح الخزنة ←</button><div id="vault-feedback" role="status"></div></div>`;$('#unlock').onclick=()=>{const val=$('#vault-code').value.replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));if(val===digits.join('')){state.questBest[l.id]=true;save();celebrate();box.innerHTML=`<div class="result"><div class="game-icon" style="font-size:70px">✦</div><h2>الملف اتفتح!</h2><p>فككت الشفرات وربطت الأفكار.</p><div class="actions"><a class="btn primary" href="#lesson/${l.id}">كمّل الدرس ←</a><a class="btn" href="#escape/${l.grade}">ملف جديد</a></div></div>`;}else{$('#vault-feedback').innerHTML='<p class="error">راجع ترتيب المفاتيح وجرب تاني.</p>';tone('wrong');}};return;}const q=questions[index],choices=shuffled(q.options.map((text,i)=>({text,correct:i===q.answer})),q.id+'vault');box.innerHTML=`<div class="quest-progress">${[0,1,2].map(i=>`<span class="${i<index?'unlocked':''}"></span>`).join('')}</div><div class="eyebrow">الشفرة ${n(index+1)} / ${n(3)}</div><h2>${esc(q.prompt)}</h2><div class="options">${choices.map((o,i)=>`<button class="option" data-clue="${i}"><span>${letters[i]}</span>${esc(o.text)}</button>`).join('')}</div><div id="clue-feedback" role="status"></div>`;$$('[data-clue]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.clue),correct=choices[i].correct;if(correct){$$('[data-clue]').forEach(x=>x.disabled=true);b.classList.add('correct');const digit=(index*3+l.unit)%9+1;quest.digits.push(digit);tone('right');$('#clue-feedback').innerHTML=`<div class="feedback"><b>كسبت المفتاح ${n(digit)}</b><p>${esc(q.explanation)}</p></div><button class="btn primary" id="next-clue">${index===2?'روح للخزنة':'افتح الشفرة التالية'} ←</button>`;$('#next-clue').onclick=()=>{quest.index++;drawQuest();};delete state.mistakes[q.id];save();}else{b.classList.add('wrong');b.disabled=true;quest.tries++;state.mistakes[q.id]={id:q.id,lesson:l.id,grade:l.grade,date:new Date().toISOString()};save();tone('wrong');$('#clue-feedback').innerHTML=`<div class="feedback"><b>الدليل محتاج نظرة تانية.</b><p>${esc(q.explanation)}</p></div>`;}});}
function mapPage(g){setGrade(g);mapGame={grade:g,order:shuffled(D.mapsets[g].map((x,i)=>({data:x,id:i})),Date.now()),index:0,correct:0,tried:false};main.innerHTML=head('تحدّي الخريطة الصامتة','اقرأ المطلوب، ثم اضغط رقم الموقع على الخريطة. يمكن استخدام الأزرار أيضًا.',g,'map')+`<section class="wrap section" style="padding-top:10px"><div id="map-area"></div></section>`;drawMap();}
function drawMap(){const{grade:g,index,order}=mapGame,box=$('#map-area');if(index===order.length){const pct=Math.round(mapGame.correct/order.length*100);state.mapBest[g]=Math.max(pct,state.mapBest[g]||0);save();if(pct>=75)celebrate();box.innerHTML=`<div class="result"><div class="score">${n(pct)}٪</div><h2>الخريطة بقت أوضح.</h2><p>${n(mapGame.correct)} مواقع صحيحة من أول محاولة، من ${n(order.length)}.</p><div class="actions"><button class="btn primary" id="map-retry">خريطة جديدة ↻</button><a class="btn" href="#portal/${g}">ارجع للدروس</a></div></div>`;$('#map-retry').onclick=()=>mapPage(g);return;}
const target=order[index],markers=D.mapsets[g].map(([name,lon,lat],i)=>{const x=(lon+180)*2,y=(90-lat)*2;return`<g class="marker" data-marker="${i}" tabindex="0" role="button" aria-label="الموقع ${i+1}" transform="translate(${x},${y})"><circle r="10"/><text y="1">${i+1}</text></g>`;}).join('');box.innerHTML=`<div class="quiz-meta"><span>الموقع ${n(index+1)} / ${n(order.length)}</span><span>حدّد الموقع: <b style="color:var(--accent)">${esc(target.data[0])}</b></span></div><div class="map-frame"><svg class="world-map" viewBox="0 0 720 360" role="group" aria-label="خريطة العالم مع مواقع مرقمة"><image href="assets/world.svg" width="720" height="360"/>${markers}</svg><p class="map-caption">خريطة تعليمية عامة؛ مواقع المعالم الواسعة تقريبية. المصدر: Natural Earth، بيانات المجال العام.</p></div><div class="map-choices" aria-label="اختيار رقم الموقع">${D.mapsets[g].map((_,i)=>`<button class="btn small" data-map-answer="${i}">الموقع ${n(i+1)}</button>`).join('')}</div><div id="map-feedback" role="status"></div>`;const choose=i=>{if(mapGame.locked)return;if(i===target.id){mapGame.locked=true;if(!mapGame.tried)mapGame.correct++;tone('right');$('#map-feedback').innerHTML=`<div class="feedback"><b>✓ ${esc(target.data[0])}</b><p>${esc(target.data[3])} — اربط الاسم بالاتجاه والمكان.</p></div><button class="btn primary" id="map-next">${index===order.length-1?'شوف النتيجة':'الموقع التالي'} ←</button>`;$('#map-next').onclick=()=>{mapGame.index++;mapGame.locked=false;mapGame.tried=false;drawMap();};}else{mapGame.tried=true;tone('wrong');$('#map-feedback').innerHTML='<div class="feedback"><b>راجع الاتجاه.</b><p>بص على القارة والموقع النسبي، وجرب تاني.</p></div>';}};$$('[data-marker]').forEach(b=>{b.onclick=()=>choose(Number(b.dataset.marker));b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(Number(b.dataset.marker));}};});$$('[data-map-answer]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.mapAnswer)));}
function timelinePage(id){const l=D.lessons.find(l=>l.id===id);if(!l||!l.timeline.length)return notFound();setGrade(l.grade);let items=shuffled(l.timeline.map((d,i)=>({d,id:i})),Date.now());if(items.every((x,i)=>x.id===i))items.reverse();timelineGame={lesson:l,items};main.innerHTML=head('رتّب الحكاية',l.title+' • من الأقدم إلى الأحدث.',l.grade)+`<section class="wrap section" style="padding-top:10px"><div class="quiz-shell" id="timeline-area"></div></section>`;drawTimeline();}
function drawTimeline(){const{lesson:l,items}=timelineGame,box=$('#timeline-area');box.innerHTML=`<h2>كل حدث.. في مكانه.</h2><p style="font-size:13px;margin-top:10px">اسحب البطاقة أو استخدم الأسهم. ابدأ بالأقدم في أعلى القائمة.</p><ol class="timeline-list">${items.map((x,i)=>`<li class="timeline-item" draggable="true" data-timeline="${i}"><b>${esc(x.d[0])}</b><p>${esc(x.d[1])}</p><button class="icon-btn" data-up="${i}" aria-label="انقل ${esc(x.d[0])} لأعلى" ${i===0?'disabled':''}>↑</button><button class="icon-btn" data-down="${i}" aria-label="انقل ${esc(x.d[0])} لأسفل" ${i===items.length-1?'disabled':''}>↓</button></li>`).join('')}</ol><button class="btn primary" id="check-timeline">افحص الترتيب ←</button><div id="timeline-feedback" role="status"></div>`;const move=(from,to)=>{if(to<0||to>=items.length)return;const[x]=items.splice(from,1);items.splice(to,0,x);drawTimeline();};$$('[data-up]').forEach(b=>b.onclick=()=>move(Number(b.dataset.up),Number(b.dataset.up)-1));$$('[data-down]').forEach(b=>b.onclick=()=>move(Number(b.dataset.down),Number(b.dataset.down)+1));let dragging=null;$$('[data-timeline]').forEach(li=>{li.ondragstart=e=>{dragging=Number(li.dataset.timeline);li.classList.add('dragging');e.dataTransfer.setData('text/plain',String(dragging));};li.ondragend=()=>li.classList.remove('dragging');li.ondragover=e=>e.preventDefault();li.ondrop=e=>{e.preventDefault();if(dragging!==null)move(dragging,Number(li.dataset.timeline));};});$('#check-timeline').onclick=()=>{const correct=items.every((x,i)=>x.id===i);tone(correct?'right':'wrong');if(correct){state.timelineBest[l.id]=true;save();celebrate();}$('#timeline-feedback').innerHTML=`<div class="feedback"><b>${correct?'✓ الأحداث في ترتيبها الصحيح':'لسه في محطات محتاجة تتبدّل.'}</b><p>${correct?'لاحظ التتابع، واربط كل محطة بالتي بعدها.':'ابدأ بأقدم تاريخ، ثم قارن كل حدث بالذي يليه.'}</p></div>${correct?`<a class="btn" href="#lesson/${l.id}">كمّل الدرس ←</a>`:''}`;};}
function group(g,code){setGrade(g);const validCode=(code||'').replace(/[^a-zA-Z0-9_-]/g,'').slice(0,20);main.innerHTML=head('معركة الحصة','نفس الكود، نفس مجموعة الأسئلة. اتفقوا على وقت البداية وقارنوا النتائج.',g,'group')+`<section class="wrap section" style="padding-top:10px"><div class="quiz-shell" id="group-area"><div class="hook-card"><h2>كوّن تحدّي مجموعتك.</h2><p>اكتب كودًا واتشاركوه. كل طالب يحل على جهازه، وبعدها يشارك بطاقة نتيجته. لا توجد لوحة ترتيب مركزية في الوضع المحلي.</p><label for="group-code">كود المجموعة / حروف إنجليزية وأرقام</label><input id="group-code" class="input" maxlength="20" dir="ltr" value="${esc(validCode)}" placeholder="MARWA-3"><div class="actions" style="margin-top:20px"><button class="btn primary" id="group-start">ابدأ المعركة ←</button><button class="btn" id="group-share">شارك رابط التحدّي</button></div><p id="group-error" class="error" role="status"></p></div></div></section>`;const getCode=()=>{const val=$('#group-code').value.trim();if(!/^[A-Za-z0-9_-]{3,20}$/.test(val)){$('#group-error').textContent='اكتب من ٣ إلى ٢٠ حرفًا إنجليزيًا أو رقمًا، ويمكن استخدام - و _.';return null;}return val.toUpperCase();};$('#group-start').onclick=()=>{const c=getCode();if(c){const seed=g+'-'+c;startQuiz(shuffled(allQuestions(g),seed).slice(0,10),{type:'group',grade:g,title:'معركة '+c,seed,target:'#group-area',seconds:600});}};$('#group-share').onclick=()=>{const c=getCode();if(c)shareText('تحدّي الدراسات مع مستر كريم شعبان — الكود '+c,location.href.split('#')[0]+'#group/'+g+'/'+c);};}
function library(g){setGrade(g);const ls=D.lessons.filter(l=>l.grade===g);main.innerHTML=head('خزانة المعرفة','ملخصات بتصميم جاهز للطباعة، ومكتبتك الأصلية محفوظة.',g,'library')+`<section class="wrap section" style="padding-top:10px"><div class="grid three"><div class="card"><div class="book-cover ${g===1?'':g===2?'blue':'gold'}"><small>مستر كريم شعبان / ${grades[g]} الإعدادي</small><b>ما وراء الحدث</b><small>أوراق شرح ومراجعة مختصرة</small></div><h3>ملفات الدروس المصممة</h3><p style="font-size:12px;margin:12px 0">كل درس له ورقة شرح وخريطة أفكار وأسئلة. افتح المعاينة ثم اطبع أو احفظ PDF من المتصفح.</p><a class="btn small" href="#handout/${ls[0].id}">شوف أول ورقة ←</a></div><div class="card"><div class="book-cover gold"><small>المكتبة الأصلية</small><b>التاريخ عبر العصور</b><small>لوحة إثرائية / PDF</small></div><h3>لوحة التاريخ الأصلية</h3><p style="font-size:12px;margin:12px 0">الملف المرفق بموقعك الأصلي. محتوى إثرائي عام، وليس مذكرة كاملة للصف.</p><div class="actions"><a href="history_note.pdf" target="_blank" rel="noopener" class="btn small">معاينة ↗</a><a href="history_note.pdf" download class="btn small">تحميل ↓</a></div></div><div class="card"><div class="book-cover blue"><small>المكتبة الأصلية</small><b>الجغرافيا في صورة</b><small>لوحة إثرائية / PDF</small></div><h3>لوحة الجغرافيا الأصلية</h3><p style="font-size:12px;margin:12px 0">أصلحت رابط التحميل ليصل إلى ملف PDF الموجود فعلًا في مشروعك.</p><div class="actions"><a href="geography_map.pdf" target="_blank" rel="noopener" class="btn small">معاينة ↗</a><a href="geography_map.pdf" download class="btn small">تحميل ↓</a></div></div></div><div style="margin-top:45px"><h2 class="unit-heading">ملفات PDF جاهزة</h2><div class="grid three">${[1,2,3].map(x=>`<div class="card"><span class="pill accent">${grades[x]} الإعدادي</span><h3 style="margin:15px 0">ما وراء الحدث</h3><p style="font-size:12px;margin-bottom:18px">شرح وتدريب مختصر • ${x===3?'٢٧':'٢٣'} صفحة • تصميم جاهز للطباعة.</p><div class="actions"><a class="btn small" href="notes/grade-${x}-ma-waraa.pdf" target="_blank" rel="noopener">معاينة ↗</a><a class="btn small primary" href="notes/grade-${x}-ma-waraa.pdf" download>تحميل ↓</a></div></div>`).join('')}</div></div><h2 class="unit-heading">اختار ورقة الدرس</h2><div class="toolbar"><input id="handout-search" class="input" type="search" aria-label="ابحث في أوراق الدروس" placeholder="ابحث عن ورقة درس…"></div><div class="grid three" id="handout-list"></div><div class="note">الحفظ بصيغة PDF يتم من نافذة الطباعة في متصفحك. يفضّل تفعيل «رسومات الخلفية» للحفاظ على ألوان الورقة.</div></section>`;const update=()=>{const q=$('#handout-search').value;$('#handout-list').innerHTML=ls.filter(l=>l.title.includes(q)).map(l=>`<a class="card" href="#handout/${l.id}"><span class="pill accent">${esc(l.subject)}</span><h3 style="margin:14px 0">${esc(l.title)}</h3><span class="btn ghost small">معاينة وطباعة ←</span></a>`).join('')||'<p>مفيش ورقة بالاسم ده.</p>';};$('#handout-search').oninput=update;update();}
function handout(id){const l=D.lessons.find(l=>l.id===id);if(!l)return notFound();setGrade(l.grade);main.innerHTML=`${head('ورقة الدرس','معاينة جاهزة للطباعة أو الحفظ بصيغة PDF.',l.grade)}<section class="wrap section" style="padding-top:10px"><div class="actions no-print"><button id="print-handout" class="btn primary">اطبع / احفظ PDF ↓</button><button id="toggle-answers" class="btn">إظهار إجابات التدريب</button><a class="btn" href="#lesson/${l.id}">الدرس التفاعلي ←</a></div><article class="paper" id="print-paper"><header><div><small>ما وراء الحدث / مستر كريم شعبان</small><h2>${esc(l.title)}</h2><p style="font-size:12px">${grades[l.grade]} الإعدادي • الترم الأول • ${esc(l.subject)}</p></div><div class="paper-stamp">افهمها..<br>اربطها..<br>وافتكرها</div></header><div class="hook-card" style="border-color:#b58e4c55;background:#ece2d0"><h3 style="color:#8a6530">افتح القضية</h3><p>${esc(l.hook)}</p></div>${l.sections.map(s=>`<section class="article-card"><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p></section>`).join('')}<h3 style="margin-top:25px">اربط الخيوط</h3><div class="mindmap"><div class="mindmap-root">${esc(l.title)}</div><div class="mindmap-branches">${l.sections.map(s=>`<div class="mind-branch"><b>${esc(s.title)}</b><p>${esc(s.body.split('。')[0])}</p></div>`).join('')}</div></div><h3>اختبر فهمك</h3>${l.questions.map((q,i)=>`<section class="article-card"><b>${n(i+1)}. ${esc(q.prompt)}</b><p>${q.options.map((o,j)=>letters[j]+') '+esc(o)).join(' — ')}</p><div class="handout-answer" hidden><p><b>الإجابة: ${esc(q.options[q.answer])}</b> — ${esc(q.explanation)}</p></div></section>`).join('')}<div class="paper-footer">مستر كريم شعبان • 01127838761 • ملفات شرح مختصرة وتدريبات أصلية، تستخدم بجانب كتاب المدرسة.</div></article></section>`;$('#print-handout').onclick=()=>window.print();$('#toggle-answers').onclick=()=>{const b=$('#toggle-answers'),show=$$('.handout-answer').some(x=>x.hidden);$$('.handout-answer').forEach(x=>x.hidden=!show);b.textContent=show?'إخفاء إجابات التدريب':'إظهار إجابات التدريب';};}
function progress(){setGrade(state.grade);const done=D.lessons.filter(l=>state.progress[l.id]?.best>=75).length,attempts=state.attempts.length,best=attempts?Math.max(...state.attempts.map(a=>Number(a.score)||0)):0;main.innerHTML=head('رحلتك.. بتتقدم.','اعرف اللي أتقنته، واللي محتاج تدريب. بيانات الوضع المحلي محفوظة في هذا المتصفح.')+`<section class="wrap section" style="padding-top:10px"><div class="dashboard-banner"><div><small>ملف المتعلم</small><h3>${state.name?esc(state.name):'اكتب اسمك وابدأ رحلتك'}</h3><p>آخر صف اخترته: ${grades[state.grade]} الإعدادي</p></div><button class="btn small" id="edit-profile">عدّل اسمك</button></div><div class="grid four"><div class="stat"><b>${n(done)}</b><p>دروس أتقنتها</p></div><div class="stat"><b>${n(attempts)}</b><p>محاولات مسجلة</p></div><div class="stat"><b>${n(best)}٪</b><p>أفضل نتيجة</p></div><div class="stat"><b>${n(Object.keys(state.mistakes).length)}</b><p>أسئلة للمراجعة</p></div></div><div class="section">${sectionHead('علامات الرحلة','كل خطوة ليها أثر.')}<div class="badge-grid">${[['✦','أول خطوة',attempts>=1],['◇','فاتح الملفات',Object.keys(state.questBest).length>=1],['⌖','مستكشف الخريطة',Object.values(state.mapBest).some(x=>x>=75)],['↕','رابط الأحداث',Object.keys(state.timelineBest).length>=1],['◎','متمكن',done>=3],['◷','ثابت الخطوة',Object.keys(state.daily).length>=3]].map(([ic,t,u])=>`<div class="badge ${u?'unlocked':''}"><span>${ic}</span><b>${t}</b><small style="display:block">${u?'حققتها':'في انتظارك'}</small></div>`).join('')}</div></div><div class="grid two"><div class="card"><h3>راجع اللي لخبطك</h3><p style="font-size:12px;margin:15px 0">ابدأ مراجعة مركزة للأسئلة اللي محتاجة تدريب.</p><a class="btn small" href="#mistakes/${state.grade}">افتح المراجعة ←</a></div><div class="card"><h3>خد نسخة من رحلتك</h3><p style="font-size:12px;margin:15px 0">صدّر بياناتك لتحتفظ بها أو تنقلها لجهاز آخر. الاستعادة تدمج أفضل النتائج والأسئلة.</p><div class="actions"><button class="btn small" id="export-progress">تصدير ↓</button><label class="btn small" for="import-progress">استعادة ↑</label><input hidden type="file" id="import-progress" accept="application/json,.json"></div></div></div><div class="section"><h2 style="font-size:24px;margin-bottom:20px">آخر محاولاتك</h2>${state.attempts.length?state.attempts.slice(-8).reverse().map(a=>`<div class="review-row" style="display:flex;justify-content:space-between;gap:15px"><div><b>${esc(a.title||'تحدّي')}</b><p style="font-size:11px">${new Date(a.date).toLocaleDateString('ar-EG')} • ${grades[a.grade]||'الإعدادي'}</p></div><span style="font:27px Georgia;color:var(--accent)">${n(Number(a.score)||0)}٪</span></div>`).join(''):'<div class="empty"><p>محاولاتك هتظهر هنا بعد أول اختبار.</p><a class="btn primary small" href="#daily/'+state.grade+'">ابدأ أول تحدّي ←</a></div>'}</div>${installPrompt?'<div class="card install-banner"><div><h3>رحلتك على جهازك</h3><p style="font-size:12px">أضف المنصة لفتحها من الشاشة الرئيسية.</p></div><button class="btn small" id="install-app">إضافة المنصة ↗</button></div>':''}<div class="card" id="cloud-card"><h3>حفظ بين الأجهزة</h3><div id="cloud-area"></div></div><p class="note">حفظ المتصفح لا يمثل حسابًا موثقًا. حذف بيانات المتصفح يمسح تقدمك المحلي؛ احتفظ بنسخة تصدير.</p></section>`;$('#edit-profile').onclick=()=>{modal(`<h2>اسمك في الرحلة</h2><label for="profile-name" style="display:block;margin:15px 0">الاسم الذي تريد ظهوره</label><input class="input" id="profile-name" maxlength="40" value="${esc(state.name)}"><button class="btn primary" id="save-profile" style="margin-top:20px">احفظ الاسم</button>`);$('#save-profile').onclick=()=>{state.name=$('#profile-name').value.trim().slice(0,40);save();$('#modal').close();progress();};};$('#export-progress').onclick=()=>download('karim-progress-'+localDay()+'.json',JSON.stringify({app:'karim-academy',version:1,state},null,2),'application/json');$('#import-progress').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024)throw Error('الملف أكبر من الحجم المسموح.');const data=JSON.parse(await f.text());if(data.app!=='karim-academy'||!data.state)throw Error('اختر ملف تقدم صادرًا من المنصة.');const restored=validateState(data.state);if(!restored)throw Error('البيانات غير صالحة.');mergeState(restored);save();toast('اتدمجت بيانات رحلتك.');progress();}catch(err){toast(err.message||'تعذر قراءة الملف.');}};const install=$('#install-app');if(install)install.onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;install.remove();}};renderCloud();}
function mergeState(other){for(const[id,p]of Object.entries(other.progress||{})){if(!D.lessons.some(l=>l.id===id)||!p||typeof p!=='object')continue;state.progress[id]={...p,...state.progress[id],best:Math.max(Number(p.best)||0,Number(state.progress[id]?.best)||0)};}state.mistakes={...other.mistakes,...state.mistakes};for(const id of Object.keys(state.mistakes))if(!questionById(id))delete state.mistakes[id];state.attempts=[...other.attempts,...state.attempts].filter((a,i,all)=>all.findIndex(x=>x.date===a.date&&x.title===a.title)===i).sort((a,b)=>String(a.date).localeCompare(String(b.date))).slice(-100);state.daily={...other.daily,...state.daily};for(const key of Object.keys(other.daily||{})){state.daily[key]={...state.daily[key],best:Math.max(Number(state.daily[key]?.best)||0,Number(other.daily[key]?.best)||0)};}state.questBest={...other.questBest,...state.questBest};state.timelineBest={...other.timelineBest,...state.timelineBest};for(const[k,v]of Object.entries(other.mapBest||{}))state.mapBest[k]=Math.max(Number(v)||0,Number(state.mapBest[k])||0);state.focusSessions=Math.max(Number(other.focusSessions)||0,Number(state.focusSessions)||0);if(!state.name)state.name=other.name;}
function focus(g){setGrade(g);clearInterval(clockTimer);main.innerHTML=head('غرفة التركيز','جلسة واحدة، هدف صغير، وخطوة واضحة.',g,'focus')+`<section class="wrap section" style="padding-top:10px"><div class="quiz-shell"><div class="hook-card"><label for="focus-goal">هدف الجلسة</label><input id="focus-goal" class="input" placeholder="هراجع درس…"><div class="toolbar"><label for="focus-length">مدة الجلسة</label><select id="focus-length" class="input"><option value="25">٢٥ دقيقة</option><option value="15">١٥ دقيقة</option><option value="5">٥ دقائق</option></select></div><div id="focus-clock" class="study-clock">25:00</div><div class="actions" style="justify-content:center"><button class="btn primary" id="focus-start">ابدأ التركيز</button><button class="btn" id="focus-pause" disabled>إيقاف مؤقت</button><button class="btn" id="focus-reset">ابدأ من جديد</button></div><p class="center" id="focus-state" style="font-size:12px;margin-top:20px">اختار هدفًا صغيرًا قبل البداية.</p></div></div></section>`;let remaining=25*60,deadline=null,started=false,pause=false;const update=()=>{$('#focus-clock').textContent=timeText(remaining);};$('#focus-length').onchange=()=>{if(started)return;remaining=Number($('#focus-length').value)*60;update();};const tick=()=>{remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));update();if(remaining===0){clearInterval(clockTimer);clockTimer=null;state.focusSessions++;save();tone('right');$('#focus-state').textContent='جلسة خلصت. خُد استراحة قصيرة، وارجع لهدفك التالي.';$('#focus-start').disabled=false;$('#focus-pause').disabled=true;started=false;}};$('#focus-start').onclick=()=>{if(!remaining)remaining=Number($('#focus-length').value)*60;started=true;pause=false;deadline=Date.now()+remaining*1000;$('#focus-start').disabled=true;$('#focus-pause').disabled=false;$('#focus-length').disabled=true;$('#focus-state').textContent=$('#focus-goal').value.trim()?'هدفك: '+$('#focus-goal').value.trim():'ركّز في مهمة واحدة.';clearInterval(clockTimer);clockTimer=setInterval(tick,250);};$('#focus-pause').onclick=()=>{if(!pause){tick();clearInterval(clockTimer);pause=true;$('#focus-pause').textContent='استئناف';}else{pause=false;deadline=Date.now()+remaining*1000;clockTimer=setInterval(tick,250);$('#focus-pause').textContent='إيقاف مؤقت';}};$('#focus-reset').onclick=()=>{clearInterval(clockTimer);started=false;pause=false;remaining=Number($('#focus-length').value)*60;update();$('#focus-start').disabled=false;$('#focus-pause').disabled=true;$('#focus-pause').textContent='إيقاف مؤقت';$('#focus-length').disabled=false;};}
function booking(){gradeClass(null);main.innerHTML=head('نتقابل في الحصة.','اختار صفك وطريقة الحصة، وجهّز رسالة الحجز على واتساب.')+`<section class="wrap section" style="padding-top:10px"><div class="booking-grid"><form id="booking-form" class="card"><h2 style="font-size:25px">ابدأ بسطرين.</h2><label for="booking-name">اسم الطالب / ولي الأمر</label><input id="booking-name" class="input" maxlength="60" required placeholder="الاسم"><label for="booking-grade">الصف</label><select id="booking-grade" class="input">${[1,2,3].map(g=>`<option value="${g}" ${state.grade===g?'selected':''}>${grades[g]} الإعدادي</option>`).join('')}</select><label for="booking-type">طريقة الحصة</label><select id="booking-type" class="input"><option>حضوري</option><option>أونلاين</option></select><label for="booking-note">تحب تسأل عن إيه؟</label><textarea id="booking-note" class="input" maxlength="1000" placeholder="المواعيد، المجموعة، أو تفاصيل الحصة…"></textarea><p style="font-size:10px;margin:18px 0">الزر يفتح واتساب برسالة جاهزة. إرسال الرسالة يتم بضغطك أنت داخل واتساب.</p><button class="btn primary" type="submit">جهّز رسالة واتساب ↗</button></form><div><div class="card"><div class="eyebrow">مستر كريم شعبان</div><h3>الدراسات أقرب.. لما نفهمها.</h3><p style="font-size:13px;margin:18px 0">شرح وحل، وواجبات ومراجعة، وأدوات بصرية وتفاعلية تساعد الطالب يشارك.</p><p style="font-size:12px">حضوري: ${esc(config.location)}<br>أونلاين: شرح مباشر وتواصل بشأن التسجيلات.</p><a class="btn small" style="margin-top:20px" href="https://wa.me/${config.phone}" target="_blank" rel="noopener">واتساب: 01127838761 ↗</a></div><div class="note">تواصل لتأكيد المواعيد والأسعار والأماكن المتاحة؛ لا يتم دفع أو تأكيد حجز عبر الموقع.</div></div></div></section>`;$('#booking-form').onsubmit=e=>{e.preventDefault();const name=$('#booking-name').value.trim();if(!name)return;const g=Number($('#booking-grade').value),type=$('#booking-type').value,note=$('#booking-note').value.trim();const message=`السلام عليكم يا مستر كريم، أنا ${name}. مهتم بحصص الدراسات للصف ${grades[g]} الإعدادي، ${type}. ممكن تفاصيل المواعيد والمجموعات؟${note?'\n'+note:''}`;window.open('https://wa.me/'+config.phone+'?text='+encodeURIComponent(message),'_blank','noopener');};}
function about(){gradeClass(null);main.innerHTML=head('مستر كريم شعبان','التاريخ يروي الزمان، والجغرافيا تفسر المكان.')+`<section class="wrap section about-grid" style="padding-top:10px"><div><h2>افهمها..<br>اربطها..<br><span style="color:var(--accent)">وافتكرها.</span></h2><p>أدرس التاريخ بكلية التربية، جامعة عين شمس، وأدرّس الدراسات الاجتماعية والتاريخ. طريقتي تبدأ بسؤال، وتستعين بالحكاية والخريطة والمقارنة، ثم تنتقل للتطبيق.</p><p>أحب أن يخرج الطالب من الحصة قادرًا على تفسير المعلومة وربطها، وأن تكون المراجعة فرصة لاكتشاف ما يحتاج إلى تدريب.</p><a href="#booking" class="btn primary">احجز حصتك ←</a><a class="btn ghost" style="margin-right:15px" href="${esc(config.facebook)}" target="_blank" rel="noopener">من أنشطة مستر كريم ↗</a></div><div class="about-photo"><img src="assets/profile.webp" alt="مستر كريم شعبان" width="500" height="500"></div></section><section class="wrap section">${sectionHead('من أرض الواقع','لحظات من الحصة.')}<div class="grid two"><figure class="card gallery-item"><img src="assets/school1.webp" alt="نشاط من صور الموقع الأصلي" loading="lazy" width="600" height="280"><figcaption>من صور أنشطة الموقع الأصلي.</figcaption></figure><figure class="card gallery-item"><img src="assets/school2.webp" alt="لقطة من المعرض الأصلي" loading="lazy" width="600" height="280"><figcaption>من المعرض الأصلي لمستر كريم.</figcaption></figure></div><div style="max-width:430px;margin:35px auto"><video controls preload="none" poster="assets/profile.webp" style="width:100%;max-height:650px;border-radius:15px;background:#000"><source src="reel.mp4" type="video/mp4">متصفحك لا يدعم تشغيل الفيديو.</video><p class="muted center" style="font-size:10px">الفيديو المرفق بالمشروع الأصلي.</p></div></section>`;}
function sources(){gradeClass(null);main.innerHTML=head('المحتوى والمصادر','تعلم واضح المصدر، مع تمييز الشرح المختصر والتدريب عن الكتاب الرسمي.')+`<section class="wrap section" style="padding-top:10px"><div class="card"><h3>ما الذي تقدمه المنصة؟</h3><p style="font-size:13px;margin-top:15px">٣٥ ملف تعلم للترم الأول، مع شرح مختصر وأسئلة وتفسيرات أصلية. هذه النسخة لا تدّعي استبدال الكتاب المدرسي أو تغطية كل تفاصيله. تم الاطلاع على فهرس كتاب الوزارة لتانية وتالتة. ترتيب أولى يستند إلى الفهرس المنشور في المرجع التالي ويحتاج مطابقة المعلم لنسخة كتابه.</p><p style="font-size:13px;margin-top:15px">ألعاب الحملة الفرنسية والابتدائي محفوظة كأنشطة إثرائية، منفصلة عن مسار الدروس الحالي. السيناريوهات في غرفة القرارات تخيّلية للتفكير، مع تفسير واضح للوقائع.</p></div>${D.sources.map(s=>`<div class="review-row"><h3>${esc(s.label)}</h3><p>${esc(s.scope)}</p><a href="${esc(s.url)}" class="btn small" target="_blank" rel="noopener">افتح المرجع ↗</a></div>`).join('')}<div class="review-row"><h3>خرائط Natural Earth</h3><p>خلفية خريطة العالم من Natural Earth، بيانات المجال العام. العلامات التعليمية تقريبية للمعالم الواسعة وليست حدودًا تفصيلية.</p><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener" class="btn small">بيانات المصدر ↗</a></div><div class="review-row"><h3>الأصول الأصلية</h3><p>صورتك وفيديوك وصور المعرض والألعاب والملفات المرفقة محفوظة من المشروع الأصلي. لم تُضف آراء طلاب أو إحصاءات نجاح مختلقة.</p></div></section>`;}
function notFound(){main.innerHTML=head('الملف ده مش موجود','ارجع للبوابة واختار ملفًا من القائمة.')+`<div class="wrap section"><a class="btn primary" href="#portal/${state.grade}">افتح بوابة صفك ←</a></div>`;}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}
function download(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function shareText(text,url){try{if(navigator.share)await navigator.share({title:'ما وراء الحدث',text,url});else if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text+'\n'+url);toast('اتنسخ الرابط والرسالة.');}else modal(`<h2>انسخ وشارك</h2><textarea class="input" rows="5" id="share-copy">${esc(text+'\n'+url)}</textarea><p style="font-size:12px;margin-top:15px">حدد النص وانسخه، وبعدها شاركه مع زملائك.</p>`);}catch(err){if(err.name!=='AbortError')toast('تعذرت المشاركة؛ جرّب نسخ الرابط من شريط العنوان.');}}
function tone(type){if(!state.prefs.sound)return;try{audioCtx||=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),v=audioCtx.createGain();o.connect(v);v.connect(audioCtx.destination);o.frequency.value=type==='right'?660:type==='wrong'?180:440;o.type='sine';v.gain.setValueAtTime(.04,audioCtx.currentTime);v.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.2);o.start();o.stop(audioCtx.currentTime+.2);}catch{}}
function celebrate(){tone('right');if(!state.prefs.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const c=$('#celebration'),ctx=c.getContext('2d');if(!ctx)return;c.width=innerWidth;c.height=innerHeight;const ps=Array.from({length:65},()=>({x:innerWidth/2,y:innerHeight*.45,dx:(Math.random()-.5)*14,dy:-(Math.random()*12+2),r:Math.random()*4+2,col:['#e9b760','#71d5b8','#94b9f8'][Math.floor(Math.random()*3)]}));let frames=0;const animate=()=>{ctx.clearRect(0,0,c.width,c.height);for(const p of ps){p.x+=p.dx;p.y+=p.dy;p.dy+=.25;ctx.fillStyle=p.col;ctx.globalAlpha=Math.max(0,1-frames/100);ctx.fillRect(p.x,p.y,p.r,p.r*2);}frames++;if(frames<100)requestAnimationFrame(animate);else ctx.clearRect(0,0,c.width,c.height);};animate();}
function prefs(){document.body.classList.toggle('motion-off',!state.prefs.motion);$('#motion-toggle').setAttribute('aria-label',state.prefs.motion?'إيقاف الحركة':'تشغيل الحركة');$('#motion-toggle').setAttribute('aria-pressed',String(state.prefs.motion));$('#sound-toggle').setAttribute('aria-label',state.prefs.sound?'إيقاف الصوت':'تشغيل الصوت');$('#sound-toggle').setAttribute('aria-pressed',String(state.prefs.sound));$('#sound-toggle').style.color=state.prefs.sound?'var(--accent)':'';}
function render(){stopQuiz();clearInterval(clockTimer);quest=null;mapGame=null;activeLesson=null;let parts=location.hash.replace(/^#/,'').split('?')[0].split('/'),[page,arg,third]=parts;page=page||'home';route=page;const g=[1,2,3].includes(Number(arg))?Number(arg):state.grade;switch(page){case'home':home();break;case'choose':home();setTimeout(()=>$('#choose')?.scrollIntoView(),0);break;case'portal':portal(g);break;case'lesson':lessonPage(arg);break;case'games':games(g);break;case'daily':daily(g);break;case'mistakes':mistakes(g);break;case'exam':exam(g);break;case'decision':decision(g);break;case'escape':escapeChooser(g);break;case'order':escapeChooser(g,'timeline');break;case'quest':questPage(arg);break;case'map':mapPage(g);break;case'timeline':timelinePage(arg);break;case'group':group(g,third);break;case'library':library(g);break;case'handout':handout(arg);break;case'progress':progress();break;case'focus':focus(g);break;case'booking':booking();break;case'about':about();break;case'sources':sources();break;default:notFound();}document.title=($('#main h1')?.textContent||'ما وراء الحدث')+' | مستر كريم شعبان';prefs();$$('.mobile-nav a').forEach(a=>a.classList.toggle('active',a.hash.split('/')[0]==='#'+page||a.hash==='#games/'+g&&['map','daily','exam','decision','escape','order','group','focus','quest','timeline'].includes(page)));if(page!=='choose'){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}}
// الربط السحابي اختياري، لا يبدأ إلا بعد إضافة إعدادات عامة صالحة.
let cloudSaveTimer;
function cloudEnabled(){return Boolean(config.cloud?.url&&config.cloud?.anonKey);}
function cloudHeaders(){return{'apikey':config.cloud.anonKey,'Authorization':'Bearer '+(cloudSession?.access_token||config.cloud.anonKey),'Content-Type':'application/json'};}
async function cloudCall(path,opts={}){const r=await fetch(config.cloud.url.replace(/\/$/,'')+path,{...opts,headers:{...cloudHeaders(),...opts.headers}});if(!r.ok){const data=await r.json().catch(()=>({}));throw Error(data.msg||data.message||data.error_description||'تعذر تنفيذ طلب الحساب.');}if(r.status===204)return null;return r.json();}
function rememberSession(s){const previous=cloudSession?.user?.id;cloudSession=s;if(s.user?.id&&s.user.id!==previous){try{const saved=validateState(JSON.parse(localStorage.getItem('karim-academy-user-'+s.user.id)));if(saved)state=saved;}catch{}}try{sessionStorage.setItem('karim-cloud-session',JSON.stringify(s));}catch{}}
async function refreshCloudSession(){if(!cloudSession?.refresh_token)return;const s=await cloudCall('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:cloudSession.refresh_token})});rememberSession(s);}
async function ensureSession(){if(cloudSession?.expires_at&&Date.now()/1000>cloudSession.expires_at-60)await refreshCloudSession();}
function scheduleCloudSave(){if(!cloudEnabled()||!cloudSession)return;clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(()=>pushCloud().catch(e=>{const area=$('#cloud-status');if(area)area.textContent='تعذرت المزامنة. تقدمك المحلي محفوظ.';}),1500);}
async function pushCloud(){await ensureSession();await cloudCall('/rest/v1/learner_progress?on_conflict=user_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:cloudSession.user.id,data:state,updated_at:new Date().toISOString()})});const a=$('#cloud-status');if(a)a.textContent='تم حفظ التقدم في حسابك.';}
async function pullCloud(){await ensureSession();const rows=await cloudCall('/rest/v1/learner_progress?select=data&user_id=eq.'+encodeURIComponent(cloudSession.user.id));if(rows?.[0]?.data){mergeState(validateState(rows[0].data)||DEFAULT);save();}}
function renderCloud(){const area=$('#cloud-area');if(!area)return;if(!cloudEnabled()){area.innerHTML='<p style="font-size:12px;margin-top:15px">المزامنة السحابية غير مفعلة في هذه النسخة. استخدم التصدير والاستعادة لنقل تقدمك بين الأجهزة.</p>';return;}if(cloudSession){area.innerHTML=`<p style="font-size:12px;margin-top:12px">الحساب: ${esc(cloudSession.user?.email||'')}</p><p id="cloud-status" class="cloud-state">تقدم المتصفح محفوظ؛ اضغط لمزامنته.</p><div class="actions" style="margin-top:15px"><button class="btn small" id="cloud-sync">مزامنة الآن</button><button class="btn small" id="cloud-logout">تسجيل خروج</button></div>`;$('#cloud-sync').onclick=async()=>{try{await pullCloud();await pushCloud();toast('تمت المزامنة.');progress();}catch(e){toast(e.message);}};$('#cloud-logout').onclick=async()=>{try{await cloudCall('/auth/v1/logout',{method:'POST'});}catch{}cloudSession=null;sessionStorage.removeItem('karim-cloud-session');try{state=validateState(JSON.parse(localStorage.getItem('karim-academy-state')))||structuredClone(DEFAULT);}catch{state=structuredClone(DEFAULT);}progress();};return;}area.innerHTML=`<form id="cloud-form"><p style="font-size:12px;margin-top:15px">سجّل دخولك لحفظ تقدمك بين الأجهزة. بيانات الدخول ترسل إلى خدمة الحسابات المُعدة للمنصة.</p><label for="cloud-email" style="font-size:12px">البريد الإلكتروني</label><input id="cloud-email" class="input" type="email" required autocomplete="email"><label for="cloud-password" style="font-size:12px">كلمة المرور</label><input id="cloud-password" class="input" type="password" minlength="8" required autocomplete="current-password"><div class="actions" style="margin-top:16px"><button class="btn primary small" type="submit">تسجيل دخول</button><button class="btn small" type="button" id="cloud-signup">إنشاء حساب</button></div><p id="cloud-status" class="cloud-state" role="status"></p></form>`;const auth=async signup=>{const f=$('#cloud-form');if(!f.reportValidity())return;const email=$('#cloud-email').value.trim(),password=$('#cloud-password').value;$('#cloud-status').textContent='جارٍ تنفيذ الطلب…';try{const s=await cloudCall(signup?'/auth/v1/signup':'/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email,password})});if(!s.access_token){$('#cloud-status').textContent='راجع بريدك لتأكيد الحساب، ثم سجّل الدخول.';return;}rememberSession(s);await pullCloud();save();renderCloud();toast('تم تسجيل الدخول.');}catch(e){$('#cloud-status').textContent=e.message;}finally{const p=$('#cloud-password');if(p)p.value='';}};$('#cloud-form').onsubmit=e=>{e.preventDefault();auth(false);};$('#cloud-signup').onclick=()=>auth(true);}
$('#year').textContent=new Date().getFullYear();$('#sound-toggle').onclick=()=>{state.prefs.sound=!state.prefs.sound;save();prefs();if(state.prefs.sound)tone('right');};$('#motion-toggle').onclick=()=>{state.prefs.motion=!state.prefs.motion;save();prefs();toast(state.prefs.motion?'تم تشغيل الحركة.':'تم إيقاف الحركة.');};$('.modal-close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});window.addEventListener('hashchange',render);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
try{cloudSession=JSON.parse(sessionStorage.getItem('karim-cloud-session'));if(cloudSession?.user?.id)state=validateState(JSON.parse(localStorage.getItem('karim-academy-user-'+cloudSession.user.id)))||structuredClone(DEFAULT);}catch{}
fetch('config.json').then(r=>r.ok?r.json():null).then(c=>{if(c){config={...config,...c};if(route==='progress')renderCloud();}}).catch(()=>{});
render();
window.AcademyDebug={get state(){return state;},get quiz(){return quiz;},get mapGame(){return mapGame;},get timelineGame(){return timelineGame;},get quest(){return quest;},validateState,mergeState,questionById,allQuestions,shuffled,rng};
})();
